// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        address originalOwner = c.owner();

        vm.prank(caller);
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        if (success) {
            assertTrue(caller == originalOwner);
        } else {
            assertTrue(c.owner() == originalOwner);
        }
    }
}
